args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?f1 ?f1Label ?d1 ?d1Label ?b1 ?f2 ?f2Label ?d2 ?d2Label ?b2 WHERE {
  VALUES (?f1 ?f2) { (dbr:Song_of_Arizona dbr:Texas_Terrors) (dbr:Texas_Terrors dbr:Song_of_Arizona) }
  ?f1 dbo:director ?d1 .
  ?f2 dbo:director ?d2 .
  ?d1 dbo:birthDate ?b1 .
  ?d2 dbo:birthDate ?b2 .
  FILTER(xsd:dateTime(?b1) < xsd:dateTime(?b2))
  OPTIONAL { ?f1 rdfs:label ?f1Label FILTER(lang(?f1Label) = "en") }
  OPTIONAL { ?d1 rdfs:label ?d1Label FILTER(lang(?d1Label) = "en") }
  OPTIONAL { ?f2 rdfs:label ?f2Label FILTER(lang(?f2Label) = "en") }
  OPTIONAL { ?d2 rdfs:label ?d2Label FILTER(lang(?d2Label) = "en") }
}

